/**
 * @name Excel formula injection
 * @description User input flowing into Excel formulas could lead to formula injection attacks
 * @kind path-problem
 * @problem.severity medium
 * @id py/excel-formula-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FormulaInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for cell value assignment with formulas in openpyxl
    exists(DataFlow::CallCfgNode call |
      (
        // Cell.value assignment with formula
        call = API::moduleImport("openpyxl").getMember("cell").getMember("Cell").getMember("value").getACall() or
        // Worksheet cell assignment
        call = API::moduleImport("openpyxl").getMember("worksheet").getMember("Worksheet").getMember("cell").getACall() or
        // Direct cell value setting via worksheet
        call = API::moduleImport("openpyxl").getMember("worksheet").getMember("Worksheet").getMember("__setitem__").getACall()
      )
      and sink = call.getArg(0)
    )
  }
}

module FormulaInjectionFlow = TaintTracking::Global<FormulaInjectionConfig>;
import FormulaInjectionFlow::PathGraph

from FormulaInjectionFlow::PathNode source, FormulaInjectionFlow::PathNode sink
where FormulaInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input from $@ flows to Excel cell value (potential formula injection).", source.getNode(), "user input"

/**
 * @name XXE in openpyxl load_workbook
 * @description User-controlled Excel files flowing to XML parsing could lead to XXE attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe-openpyxl
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XxeOpenpyxlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source is the file argument to load_workbook
    exists(API::CallNode loadCall |
      loadCall = API::moduleImport("openpyxl").getMember("load_workbook").getACall() and
      source = loadCall.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // XML parsing operations in openpyxl
    exists(API::CallNode call |
      (
        // Check for XML parsing from xml.etree
        call = API::moduleImport("xml").getMember("etree").getMember(["ElementTree", "parse", "fromstring", "XML"]).getACall() or
        // Check for lxml parsing
        call = API::moduleImport("lxml").getMember(["etree", "objectify"]).getMember(["parse", "fromstring", "XML"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module XxeOpenpyxlFlow = TaintTracking::Global<XxeOpenpyxlConfig>;
import XxeOpenpyxlFlow::PathGraph

from XxeOpenpyxlFlow::PathNode source, XxeOpenpyxlFlow::PathNode sink
where XxeOpenpyxlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled Excel file flows to XML parser without XXE protection.", source.getNode(), "file input"
